import importlib.util
spec=importlib.util.spec_from_file_location("pl_lib","build/founder-mode/part-lifecycle/pl_lib.py")
L=importlib.util.module_from_spec(spec); spec.loader.exec_module(L)
Q=L.Q
def src(n,title): return (f'Epic SV-10647; "Parts Lifecycle Update" PRD (Confluence 829227015, IN REVIEW 2026-09-09), Story {n} ({title}); '
    f'design canvas Vz6rprcWyP16tYxzM1kdeE; read 30 Sep 2026.')
INV='You are on the Parts -> Inventory page on the build under test, with permission to view inventory parts.'
MANAGE='You hold the "Part Library & Inventory - Delete" permission (needed to change status/tracking).'
def seed_parts(): return ('Seed a few inventory parts (tag throwaway data "ZZAUTOTEST", e.g. part number "ZZAUTOTEST-PKG-1", name "ZZAUTOTEST package part") via New Inventory Part.')

S1=[
{"anchors":["S1-R1","S1-R2","S1-R3","S1-R4"],"title":"Active/Inactive tabs, Active selected, each lists its own state",
 "pre":[INV,seed_parts()+' Set at least one part inactive so both tabs have content.'],
 "steps":['Open the Parts -> Inventory page.','Read the two tabs and which is selected.','Open the Active tab and confirm every listed part is active.','Open the Inactive tab and confirm every listed part is inactive.'],
 "results":['The Inventory list shows two tabs, Active and Inactive, with Active selected when the page opens.',
   'The Active tab lists only active parts and the Inactive tab lists only inactive parts.'],
 "source":src(1,"Active / Inactive tabs"),"quotes":Q("S1-R1","S1-R2","S1-R3","S1-R4")},
{"anchors":["S1-R5","S1-R6","S1-R7","S1-N1"],"title":"All active on release; tab switch clears selection; tabs alike; empty state",
 "pre":[INV,MANAGE],
 "steps":['On release day, confirm every existing part is on the Active tab (none start inactive).','On the Active tab, tick some rows (in bulk mode), then switch to the Inactive tab; check the selection.','Apply a search, a filter and a sort on each tab and compare behaviour.','View the Inactive tab in a shop with no inactive parts.'],
 "results":['Every part that exists when the feature is released is active; switching tabs clears any rows the user had selected.',
   'Search, filters and sort work the same way on both tabs; with no inactive parts, the Inactive tab shows an empty state (no parts listed).'],
 "source":src(1,"Active / Inactive tabs"),"quotes":Q("S1-R5","S1-R6","S1-R7","S1-N1")},
]

